  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#7cfc00");
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // Green hills
  brush.fill("#228b22");
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // Sun
  brush.fill("#ff4500");
  brush.beginShape();
  brush.vertex(200, 100);
  brush.vertex(250, 80);
  brush.vertex(220, 100);
  brush.endShape(true);
}

