  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87ceeb", 100);
  brush.fillBleed(0.5);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(200, 400);
  brush.endShape(true);

  // Green hills
  brush.fill("#4682b4", 100);
  brush.fillBleed(0.3);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(200, 400);
  brush.endShape(true);

  // Sun
  brush.fill("#f0a91a", 100);
  brush.fillBleed(0.8);
  brush.beginShape();
  brush.vertex(150, 100);
  brush.vertex(350, 100);
  brush.vertex(250, 50);
  brush.endShape(true);
}
```

