  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87ceeb", 100);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(200, 400);
  brush.endShape(true);

  // Green hills
  brush.fill("#006400", 100);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(200, 400);
  brush.endShape(true);

  // Sun
  brush.fill("#ff4500", 100);
  brush.beginShape();
  brush.vertex(100, 100);
  brush.vertex(300, 100);
  brush.vertex(200, 200);
  brush.endShape(true);
}
